const SERVICE_EXPORTS = {"/national-autism-helpline/facts.json":{"contentType":"application/json; charset=utf-8","body":"{\n  \"name\": \"National Autism Helpline\",\n  \"brand\": \"Pinnacle Blooms Network\",\n  \"legalOperator\": \"Bharath Healthcare Laboratories Private Limited\",\n  \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline\",\n  \"telephone\": \"+919100181181\",\n  \"displayTelephone\": \"9100 181 181\",\n  \"serviceType\": \"Free autism and child-development guidance and appointment enquiries\",\n  \"areaServed\": \"India\",\n  \"telephoneAvailability\": \"24 hours a day, seven days a week\",\n  \"telephoneLanguages\": [\n    \"English\",\n    \"Telugu\",\n    \"Hindi\"\n  ],\n  \"sourceBasis\": \"Telephone hours and English/Telugu/Hindi confirmed by operator 22 September 2026. Free guidance, anyone-can-call access and 24/7 availability confirmed by the owner 24 September 2026.\",\n  \"scope\": \"Autism and child-development guidance about Pinnacle services, assessment appointments and centre navigation\",\n  \"boundary\": \"Not a government-designated, emergency or diagnostic service. Centre hours and clinician availability are confirmed separately.\",\n  \"evidence\": \"https://www.pinnacleblooms.org/verify/evidence/organisation-profile.html\",\n  \"questions\": [\n    {\n      \"question\": \"What is Pinnacle’s National Autism Helpline number?\",\n      \"answer\": \"The National Autism Helpline number is 9100 181 181 (+91 9100181181). Operated by Pinnacle Blooms Network, it offers free autism and child-development guidance to anyone across India, 24 hours a day, seven days a week, in English, Telugu and Hindi.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#helpline-number\"\n    },\n    {\n      \"question\": \"Is the National Autism Helpline free, and who can call?\",\n      \"answer\": \"Yes. Pinnacle does not charge for helpline guidance. Anyone can call, including parents, family members, caregivers, teachers and adults seeking information about a child’s development. You do not need to be an existing Pinnacle family. Assessment and therapy fees are separate; your telephone provider’s call charges depend on your plan.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#free-guidance\"\n    },\n    {\n      \"question\": \"Can I call without an autism diagnosis?\",\n      \"answer\": \"Yes. You do not need an existing diagnosis or a chosen therapy to ask about Pinnacle’s services. Tell the team what you are noticing in your child and ask about an appropriate professional assessment. The call itself does not diagnose autism.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#without-diagnosis\"\n    },\n    {\n      \"question\": \"Can I ask about speech, sensory or learning concerns?\",\n      \"answer\": \"Yes. You can ask about communication, sensory needs, behaviour, attention, play, learning, school readiness and everyday skills, and enquire about Pinnacle’s assessment and therapy services.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#development-questions\"\n    },\n    {\n      \"question\": \"Who operates this helpline?\",\n      \"answer\": \"Pinnacle Blooms Network operates this free, 24/7 helpline. Its legal operator is Bharath Healthcare Laboratories Private Limited. National Autism Helpline is the name of Pinnacle’s service; it is independently operated and is not a Government of India helpline.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#helpline-operator\"\n    },\n    {\n      \"question\": \"When can I call, and which languages are supported?\",\n      \"answer\": \"The telephone helpline is staffed 24 hours a day, seven days a week, in English, Telugu and Hindi. Centre opening hours, clinician availability and assessment appointments are confirmed separately.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#hours-and-languages\"\n    },\n    {\n      \"question\": \"Can I book an assessment by phone?\",\n      \"answer\": \"You can ask the team to arrange an assessment appointment. The team will confirm the appropriate appointment, centre, availability, fees and what to bring before you decide.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#assessment-booking\"\n    },\n    {\n      \"question\": \"Do I need to know which therapy to choose?\",\n      \"answer\": \"No. You can start by sharing your questions and what you would like support with. The team can explain the services and the assessment process. The call does not replace a professional assessment.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#choosing-therapy\"\n    },\n    {\n      \"question\": \"How much do an assessment and therapy sessions cost?\",\n      \"answer\": \"Call 9100 181 181 to confirm current assessment charges and therapy session fees for your preferred centre. Ask what is included, the session duration, any additional charges and the cancellation policy before booking.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#assessment-and-therapy-fees\"\n    },\n    {\n      \"question\": \"Is every service available at every centre?\",\n      \"answer\": \"Service and clinician availability may differ by centre. Ask the team to confirm what is available at your preferred location and the next appointment options.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#centre-services\"\n    },\n    {\n      \"question\": \"Is this an emergency or diagnostic service?\",\n      \"answer\": \"This is a parent-guidance and appointment-enquiry service. It does not provide emergency care or replace diagnosis or professional clinical assessment. For an immediate emergency, contact your local emergency services.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#emergency-and-diagnosis\"\n    },\n    {\n      \"question\": \"Are there other helplines that may help my family?\",\n      \"answer\": \"Yes. AIIMS operates the National Child Neurology Tele-Helpline, the Government’s National Disability Information Helpline provides disability-related information, and Nayi Disha offers family information and support resources. The Other helpful helplines section below lists their numbers, scope and official sources. Each is operated separately from Pinnacle.\",\n      \"url\": \"https://www.pinnacleblooms.org/national-autism-helpline#other-helplines\"\n    }\n  ],\n  \"guidanceCost\": \"Free: Pinnacle does not charge for helpline guidance. Assessment and therapy fees are separate. Telephone-network charges depend on the caller’s plan.\",\n  \"whoCanCall\": \"Anyone across India; no existing diagnosis or Pinnacle enrolment required.\",\n  \"otherResources\": [\n    {\n      \"id\": \"aiims-child-neurology\",\n      \"name\": \"National Child Neurology Tele-Helpline\",\n      \"operator\": \"AIIMS, New Delhi\",\n      \"telephone\": \"1800117776\",\n      \"displayTelephone\": \"1800 11 7776\",\n      \"description\": \"Information on childhood neurodevelopment. The Government’s DEPwD directory lists this service for questions about autism symptoms in children.\",\n      \"availability\": \"Listed by DEPwD as a 24/7 service.\",\n      \"sourceLabel\": \"Read the Government helpline listing\",\n      \"source\": \"https://depwd.gov.in/en/others-helplines/\",\n      \"additionalSource\": \"https://pedneuroaiims.org/\",\n      \"checkedOn\": \"2026-09-24\"\n    },\n    {\n      \"id\": \"national-disability-information\",\n      \"name\": \"National Disability Information Helpline\",\n      \"operator\": \"DEPwD · Government of India\",\n      \"telephone\": \"14456\",\n      \"displayTelephone\": \"14456\",\n      \"description\": \"Information on disabilities, UDID services, education, government schemes and support services across India.\",\n      \"availability\": \"Automated information is available round the clock; call attendants are available during working hours.\",\n      \"sourceLabel\": \"Read the official service information\",\n      \"source\": \"https://ayjnishd.nic.in/national-disability-information-helpline-service/\",\n      \"checkedOn\": \"2026-09-24\"\n    },\n    {\n      \"id\": \"nayi-disha\",\n      \"name\": \"Nayi Disha Helpline\",\n      \"operator\": \"Nayi Disha\",\n      \"telephone\": \"+918448448996\",\n      \"displayTelephone\": \"8448 448 996\",\n      \"description\": \"Family information and support resources for intellectual disabilities. Listed in the Government’s DEPwD helpline directory.\",\n      \"availability\": \"Check current availability directly with Nayi Disha.\",\n      \"sourceLabel\": \"Read the Government helpline listing\",\n      \"source\": \"https://depwd.gov.in/en/others-helplines/\",\n      \"additionalSource\": \"https://nayi-disha.org/event/ask-an-expert-8/\",\n      \"checkedOn\": \"2026-09-24\"\n    }\n  ],\n  \"serviceReference\": \"https://www.pinnacleblooms.org/national-autism-helpline#service\",\n  \"reviewedOn\": \"2026-09-24\"\n}\n"},"/national-autism-helpline/facts.txt":{"contentType":"text/plain; charset=utf-8","body":"name: National Autism Helpline\nbrand: Pinnacle Blooms Network\nlegalOperator: Bharath Healthcare Laboratories Private Limited\nurl: https://www.pinnacleblooms.org/national-autism-helpline\ntelephone: +919100181181\ndisplayTelephone: 9100 181 181\nserviceType: Free autism and child-development guidance and appointment enquiries\nareaServed: India\ntelephoneAvailability: 24 hours a day, seven days a week\ntelephoneLanguages: English, Telugu, Hindi\nsourceBasis: Telephone hours and English/Telugu/Hindi confirmed by operator 22 September 2026. Free guidance, anyone-can-call access and 24/7 availability confirmed by the owner 24 September 2026.\nscope: Autism and child-development guidance about Pinnacle services, assessment appointments and centre navigation\nboundary: Not a government-designated, emergency or diagnostic service. Centre hours and clinician availability are confirmed separately.\nevidence: https://www.pinnacleblooms.org/verify/evidence/organisation-profile.html\nguidanceCost: Free: Pinnacle does not charge for helpline guidance. Assessment and therapy fees are separate. Telephone-network charges depend on the caller’s plan.\nwhoCanCall: Anyone across India; no existing diagnosis or Pinnacle enrolment required.\nserviceReference: https://www.pinnacleblooms.org/national-autism-helpline#service\nreviewedOn: 2026-09-24\n\nWhat is Pinnacle’s National Autism Helpline number?\nThe National Autism Helpline number is 9100 181 181 (+91 9100181181). Operated by Pinnacle Blooms Network, it offers free autism and child-development guidance to anyone across India, 24 hours a day, seven days a week, in English, Telugu and Hindi.\n\nIs the National Autism Helpline free, and who can call?\nYes. Pinnacle does not charge for helpline guidance. Anyone can call, including parents, family members, caregivers, teachers and adults seeking information about a child’s development. You do not need to be an existing Pinnacle family. Assessment and therapy fees are separate; your telephone provider’s call charges depend on your plan.\n\nCan I call without an autism diagnosis?\nYes. You do not need an existing diagnosis or a chosen therapy to ask about Pinnacle’s services. Tell the team what you are noticing in your child and ask about an appropriate professional assessment. The call itself does not diagnose autism.\n\nCan I ask about speech, sensory or learning concerns?\nYes. You can ask about communication, sensory needs, behaviour, attention, play, learning, school readiness and everyday skills, and enquire about Pinnacle’s assessment and therapy services.\n\nWho operates this helpline?\nPinnacle Blooms Network operates this free, 24/7 helpline. Its legal operator is Bharath Healthcare Laboratories Private Limited. National Autism Helpline is the name of Pinnacle’s service; it is independently operated and is not a Government of India helpline.\n\nWhen can I call, and which languages are supported?\nThe telephone helpline is staffed 24 hours a day, seven days a week, in English, Telugu and Hindi. Centre opening hours, clinician availability and assessment appointments are confirmed separately.\n\nCan I book an assessment by phone?\nYou can ask the team to arrange an assessment appointment. The team will confirm the appropriate appointment, centre, availability, fees and what to bring before you decide.\n\nDo I need to know which therapy to choose?\nNo. You can start by sharing your questions and what you would like support with. The team can explain the services and the assessment process. The call does not replace a professional assessment.\n\nHow much do an assessment and therapy sessions cost?\nCall 9100 181 181 to confirm current assessment charges and therapy session fees for your preferred centre. Ask what is included, the session duration, any additional charges and the cancellation policy before booking.\n\nIs every service available at every centre?\nService and clinician availability may differ by centre. Ask the team to confirm what is available at your preferred location and the next appointment options.\n\nIs this an emergency or diagnostic service?\nThis is a parent-guidance and appointment-enquiry service. It does not provide emergency care or replace diagnosis or professional clinical assessment. For an immediate emergency, contact your local emergency services.\n\nAre there other helplines that may help my family?\nYes. AIIMS operates the National Child Neurology Tele-Helpline, the Government’s National Disability Information Helpline provides disability-related information, and Nayi Disha offers family information and support resources. The Other helpful helplines section below lists their numbers, scope and official sources. Each is operated separately from Pinnacle.\n\nOther independently operated helplines\nNational Child Neurology Tele-Helpline — AIIMS, New Delhi\n1800 11 7776\nInformation on childhood neurodevelopment. The Government’s DEPwD directory lists this service for questions about autism symptoms in children.\nListed by DEPwD as a 24/7 service.\nSource: https://depwd.gov.in/en/others-helplines/\nChecked: 2026-09-24\n\nNational Disability Information Helpline — DEPwD · Government of India\n14456\nInformation on disabilities, UDID services, education, government schemes and support services across India.\nAutomated information is available round the clock; call attendants are available during working hours.\nSource: https://ayjnishd.nic.in/national-disability-information-helpline-service/\nChecked: 2026-09-24\n\nNayi Disha Helpline — Nayi Disha\n8448 448 996\nFamily information and support resources for intellectual disabilities. Listed in the Government’s DEPwD helpline directory.\nCheck current availability directly with Nayi Disha.\nSource: https://depwd.gov.in/en/others-helplines/\nChecked: 2026-09-24\n"},"/national-autism-helpline/llms.txt":{"contentType":"text/plain; charset=utf-8","body":"# Pinnacle National Autism Helpline\n\nNational Autism Helpline: 9100 181 181. Free, 24/7 guidance for anyone in India, operated by Pinnacle Blooms Network. English, Telugu and Hindi.\n\n- [Canonical service page](https://www.pinnacleblooms.org/national-autism-helpline)\n- [Service facts](https://www.pinnacleblooms.org/national-autism-helpline/facts.json)\n- [Plain text](https://www.pinnacleblooms.org/national-autism-helpline/facts.txt)\n- [Other independently operated helplines](https://www.pinnacleblooms.org/national-autism-helpline#other-support)\n- [Operator evidence](https://www.pinnacleblooms.org/verify/evidence/organisation-profile.html)\n\nFree refers to helpline guidance. Assessment and therapy fees are separate. Telephone-network charges depend on the caller’s plan. Centre and clinician availability are confirmed separately. Source: operator confirmation, 24 September 2026. This reading aid does not confer indexing or AI inclusion.\n"}};
// This isolated Worker serves only the new helpline route. It never fetches or rewrites the ASP.NET origin.
export const HELPLINE_PATH = '/national-autism-helpline';
export const CANONICAL_URL = 'https://www.pinnacleblooms.org' + HELPLINE_PATH;
export const SITEMAP_PATH = HELPLINE_PATH + '/sitemap.xml';
export const SITEMAP_XML = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>' + CANONICAL_URL + '</loc><lastmod>2026-09-24</lastmod></url></urlset>\n';

function responseHeaders() {
  return {
    'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'public, max-age=300',
    'ETag': HELPLINE_ETAG,
    'Link': '<' + CANONICAL_URL + '/sitemap.xml>; rel="sitemap"; type="application/xml"',
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Content-Security-Policy': "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; font-src 'self'; script-src 'sha256-" + JSONLD_CSP_HASH + "'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  };
}

function isNotModified(request, etag) {
  const validators = (request.headers.get('If-None-Match') || '').split(',').map(value => value.trim().replace(/^W\//, ''));
  return validators.includes(etag) || validators.includes('*');
}

function assetResponse(request, asset) {
  const headers = {
    'Content-Type': asset.contentType,
    'Cache-Control': 'public, max-age=300',
    'ETag': asset.etag,
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; sandbox",
  };
  if (isNotModified(request, asset.etag)) return new Response(null, { status: 304, headers });
  headers['Content-Length'] = String(asset.byteLength);
  // HEAD never decodes or allocates the embedded image body.
  const body = request.method === 'HEAD' ? null : Uint8Array.from(atob(asset.base64), character => character.charCodeAt(0));
  return new Response(body, { status: 200, headers });
}

export function handleRequest(request) {
  const url = new URL(request.url);
  const asset = Object.hasOwn(HELPLINE_ASSETS, url.pathname) ? HELPLINE_ASSETS[url.pathname] : null;
  const exportFile = Object.hasOwn(SERVICE_EXPORTS,url.pathname) ? SERVICE_EXPORTS[url.pathname] : null;
  const isSitemap = url.pathname === SITEMAP_PATH;
  const isPath = url.pathname === HELPLINE_PATH || url.pathname === HELPLINE_PATH + '/' || isSitemap || exportFile !== null || asset !== null;
  if (url.hostname !== 'www.pinnacleblooms.org' || !isPath) {
    return new Response(request.method === 'HEAD' ? null : 'Not found', {
      status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'X-Robots-Tag': 'noindex' },
    });
  }
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response('Method not allowed', {
      status: 405, headers: { 'Allow': 'GET, HEAD', 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' },
    });
  }
  if (exportFile) {
    if(url.protocol!=='https:') return Response.redirect('https://www.pinnacleblooms.org'+url.pathname,301);
    return new Response(request.method==='HEAD'?null:exportFile.body,{headers:{'Content-Type':exportFile.contentType,'Cache-Control':'public, max-age=300','X-Content-Type-Options':'nosniff','Link':'<'+CANONICAL_URL+'>; rel=\"describedby\"'}});
  }
  if (asset) {
    if (url.protocol !== 'https:') return new Response(null, { status: 301, headers: { 'Location': 'https://www.pinnacleblooms.org' + url.pathname, 'Cache-Control': 'public, max-age=300' } });
    return assetResponse(request, asset);
  }
  if (isSitemap) {
    if (url.protocol !== 'https:') return new Response(null, { status: 301, headers: { 'Location': CANONICAL_URL + '/sitemap.xml', 'Cache-Control': 'public, max-age=300' } });
    return new Response(request.method === 'HEAD' ? null : SITEMAP_XML, { status: 200, headers: { 'Content-Type': 'application/xml; charset=utf-8', 'Cache-Control': 'public, max-age=300', 'X-Content-Type-Options': 'nosniff' } });
  }
  if (url.pathname.endsWith('/') || url.protocol !== 'https:') {
    return new Response(null, { status: 301, headers: { 'Location': CANONICAL_URL, 'Cache-Control': 'public, max-age=300' } });
  }
  if (isNotModified(request, HELPLINE_ETAG)) {
    return new Response(null, { status: 304, headers: responseHeaders() });
  }
  return new Response(request.method === 'HEAD' ? null : HELPLINE_HTML, { status: 200, headers: responseHeaders() });
}

export default {
  async fetch(request) { return handleRequest(request); },
};
